#!/usr/bin/env python3
"""Cauchy derivative budget for E6 pivot 17 using its analyticity through E8."""
import json
from pathlib import Path
root=Path(__file__).parents[1]/'results';r8=json.loads((root/'complex_schur_ellipse_L0649_L065_rho8_scout64.json').read_text())['samples'];r6=json.loads((root/'complex_schur_ellipse_L0649_L065_rho6_scout256.json').read_text())['samples'];p8=[abs(complex(x['strong_ldl_pivot_real'][17],x['strong_ldl_pivot_imag'][17])) for x in r8];p6=[abs(complex(x['strong_ldl_pivot_real'][17],x['strong_ldl_pivot_imag'][17])) for x in r6];h=.0005
def axes(r):return h*(r+r**-1)/2,h*(r-r**-1)/2
a6,b6=axes(6);a8,b8=axes(8);sep=min(a8-a6,b8-b6);M=8e-6;der=M/sep;half=max(abs(complex(r6[(i+1)%len(r6)]['L_real'],r6[(i+1)%len(r6)]['L_imag'])-complex(r6[i]['L_real'],r6[i]['L_imag'])) for i in range(len(r6)))/2;var=der*half;lower=min(p6)-var;out={'schema':'marici.voevodsky.gate3-final-strong-pivot-E6-from-E8.v1','sampled_E8_pivot17_max':max(p8),'adopted_directed_E8_pivot17_bound':M,'E6_E8_separation':sep,'cauchy_derivative_bound_E6':der,'E6_half_chord_256':half,'arc_variation':var,'sampled_E6_pivot17_min':min(p6),'conditional_E6_pivot17_floor':lower,'passed_conditionally':lower>0,'analyticity_condition':'pivots 0-16 are zero-free through E8; zeros of pivot17 do not obstruct analyticity of pivot17 itself','passed':False,'remaining':'direct E8 magnitude cover <=8e-6 and directed no-pole certificates for pivots 0-16','rh_proved':False};p=root/'gate3_final_strong_pivot_E6_from_E8.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
